#include<bits/stdc++.h>
using namespace std;
long long l,n,m,a[500005],ans;
int main(){
	freopen("crystal.in","r",stdin);
	freopen("crystal.out","w",stdout);
	cin>>n>>m;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}
	l=max(a[1]-a[2],a[2]-a[1]);
	for(int i=1;i<n;i++){
		ans+=l*i;
		if(ans>m){
			cout<<i;
			break;
		}
	}
	return 0;
}
